## 4. Suggested “secure baseline” implementation

Below is a minimal, yet much safer, version of `app.js` that addresses the points above. You can copy‑paste it or adapt it to your needs.

```js
// app.js – secure baseline
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// ----- Basic security middlewares -----
app.use(helmet());                     // Sets common security headers
app.use(cors({                          // Adjust the origin list for your environment
  origin: process.env.CORS_ORIGIN ? process.env.CORS_ORIGIN.split(',') : false,
  methods: ['GET', 'POST', 'OPTIONS'],
}));
app.set('trust proxy', 1);             // Trust first proxy when behind a reverse proxy

// ----- Rate limiting -----
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ----- Routes -----
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// In a real service this endpoint would be protected
app.get('/users', (req, res) => {
  // Example: return a *sanitized* list or require auth
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

// ----- Global error handler (must be after routes) -----
app.use((err, _req, res, _next) => {
  // Log the error internally (use a proper logger in production)
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// ----- Server start -----
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

