// app.js – hardened version with environment‑driven configuration
require('dotenv').config();               // <-- loads .env (ignored by git)

const express = require('express');
const helmet = require('helmet');
const cors    = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ------------------------------------------------------------------
// 1️⃣  Security middleware
// ------------------------------------------------------------------
app.use(helmet());                         // standard security headers
app.use(cors({                               // restrict origins – adjust as needed
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
}));

// Simple rate limiting – 100 requests per 15‑minute window per IP
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// ------------------------------------------------------------------
// 2️⃣  Routes
// ------------------------------------------------------------------
app.get('/health', (req, res) => {
  // Avoid exposing a timestamp unless you really need it
  res.json({ status: 'ok' });
});

app.get('/users', (req, res) => {
  // Example data – no real e‑mail addresses
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' }
  ]);
});

// ------------------------------------------------------------------
// 3️⃣  Central error handler (prevents stack‑trace leakage)
// ------------------------------------------------------------------
app.use((err, _req, res, _next) => {
  console.error(err);                     // internal logging
  res.status(500).json({ error: 'Internal Server Error' });
});

// ------------------------------------------------------------------
// 4️⃣  Server start – all values come from the environment
// ------------------------------------------------------------------
const PORT = parseInt(process.env.PORT, 10) || 3000;
const HOST = process.env.HOST || '127.0.0.1';   // default bind to localhost

app.listen(PORT, HOST, () => {
  console.log(`🚀 Server listening at http://${HOST}:${PORT}`);
});

module.exports = app;
```

