Below is a **minimal, production‑ready starter** that addresses the high‑impact gaps while keeping the original functionality intact.

```js
// app.js
require('dotenv').config();           // Load .env in development only
const express = require('express');
const helmet = require('helmet');
const cors   = require('cors');
const rateLimit = require('express-rate-limit');
const pino = require('pino');
const expressPino = require('express-pino-logger');

const app = express();

// ------------ Middleware ------------ //
app.use(helmet());                     // Secure HTTP headers
app.use(cors({                         // Restrict origins in prod
  origin: process.env.CORS_ORIGIN?.split(',') || '*',
}));
app.use(express.json());               // In case you add POST later

// Rate limiting – 100 req/min per IP (adjust as needed)
const limiter = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Structured logging (pino)
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
app.use(expressPino({ logger }));

// ------------ Routes ------------ //
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // Static data – in a real app replace with DB call & proper auth
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ------------ Error handling ------------ //
app.use((err, req, res, next) => {
  // Log the error (stack is hidden from client)
  logger.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// ------------ Server startup ------------ //
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

// Graceful shutdown
const shutdown = () => {
  logger.info('Received shutdown signal – closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
};
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;
```

### What the patch adds

| Feature | Implementation |
|---------|----------------|
| **Environment loading** | `dotenv` (dev only). |
| **Security headers** | `helmet()` – automatically sets CSP, X‑XSS‑Protection, etc. |
| **CORS** | Configurable via `CORS_ORIGIN` env var; defaults to `*` for ease of testing. |
| **Rate limiting** | `express-rate-limit` – throttles abusive IPs. |
| **Structured logging** | `pino` + `express-pino-logger`. |
| **Error handling** | Central middleware that logs and returns a generic 500 response. |
| **Port configuration** | `process.env.PORT`. |
| **Graceful shutdown** | Listeners for `SIGTERM`/`SIGINT`. |
| **Future‑proof** | `express.json()` is added so later POST/PUT endpoints can parse JSON safely. |

