/* app.js – Secure version */

require('dotenv').config();                // Load env vars from .env (never commit .env)
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const hpp = require('hpp');

const app = express();

/* ----------------- Security Middleware ----------------- */
app.use(helmet());                         // Sets a robust set of HTTP headers
app.use(hpp());                            // Protects against HTTP Parameter Pollution
app.disable('x-powered-by');               // Hide Express fingerprint

/* CORS – adjust origin(s) to your client(s) */
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || [], // e.g. "https://myapp.com"
    methods: ['GET'],
    credentials: false,
  })
);

/* Rate limiting – 100 requests per 15 min per IP (tune as needed) */
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

/* ------------ Optional: JSON body parsing (if you add POST) ------------ */
app.use(express.json());

/* ----------------- Health endpoint (internal only) ----------------- */
const healthToken = process.env.HEALTH_TOKEN; // secret token, optional
app.get('/health', (req, res) => {
  // If a token is configured, require it
  if (healthToken && req.headers['x-health-token'] !== healthToken) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/* ----------------- Protected /users endpoint ----------------- */
function requireAuth(req, res, next) {
  // Stub – replace with real auth (JWT, session, API‑key, etc.)
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // TODO: Verify token, attach user to req, etc.
  next();
}

app.get('/users', requireAuth, (req, res) => {
  // In a real app, pull this from a DB & never expose raw e‑mail addresses
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

/* ----------------- Global error handler (no stack traces in prod) ----------------- */
app.use((err, _req, res, _next) => {
  console.error(err); // always log for ops
  const isProd = process.env.NODE_ENV === 'production';
  const payload = { error: 'Internal Server Error' };
  if (!isProd) payload.details = err.message; // helpful in dev only
  res.status(500).json(payload);
});

/* ----------------- Server start (HTTPS optional) ----------------- */
if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  // If you have TLS cert/key in env vars or files, use https.createServer()
  // For simplicity we stay on HTTP here (TLS termination should be done upstream)
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

/* Export for testing */
module.exports = app;
```

